-- 2026 年會出席分會名錄（區域 → 分會）
-- Generated by scripts/generate-event-chapters-sql.mjs

CREATE TABLE IF NOT EXISTS bni_event_regions (
  id text PRIMARY KEY,
  area_group text NOT NULL,
  label_zh text NOT NULL,
  sort_order int NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS bni_event_chapters (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  region_id text NOT NULL REFERENCES bni_event_regions(id) ON DELETE CASCADE,
  short_name text NOT NULL,
  full_name text NOT NULL,
  is_ateam_roster boolean NOT NULL DEFAULT false,
  sort_order int NOT NULL DEFAULT 0,
  UNIQUE(region_id, short_name)
);

CREATE INDEX IF NOT EXISTS bni_event_chapters_region_idx ON bni_event_chapters(region_id);

ALTER TABLE bni_event_regions ENABLE ROW LEVEL SECURITY;
ALTER TABLE bni_event_chapters ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS bni_event_regions_read ON bni_event_regions;
CREATE POLICY bni_event_regions_read ON bni_event_regions FOR SELECT USING (true);
DROP POLICY IF EXISTS bni_event_chapters_read ON bni_event_chapters;
CREATE POLICY bni_event_chapters_read ON bni_event_chapters FOR SELECT USING (true);

TRUNCATE bni_event_chapters, bni_event_regions CASCADE;



CREATE OR REPLACE FUNCTION bni_get_event_chapters()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public STABLE AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'areaGroup', r.area_group,
        'regionId', r.id,
        'regionLabel', r.label_zh,
        'chapters', (
          SELECT COALESCE(jsonb_agg(c.short_name ORDER BY c.sort_order), '[]'::jsonb)
          FROM bni_event_chapters c WHERE c.region_id = r.id
        )
      ) ORDER BY r.sort_order
    )
    FROM bni_event_regions r
  ), '[]'::jsonb);
END; $$;

GRANT EXECUTE ON FUNCTION bni_get_event_chapters() TO anon, authenticated;

